document.addEventListener("change",e=>{if(e.target.id!=="hs-file")return;const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const m=Math.min(1,600/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=Math.max(1,im.width*m);c.height=Math.max(1,im.height*m);c.getContext("2d").drawImage(im,0,0,c.width,c.height);CL=c.toDataURL(f.type==="image/jpeg"?"image/jpeg":"image/png",.9);try{localStorage.setItem("hero-logo",CL)}catch(x){}setLogo()};im.src=r.result};r.readAsDataURL(f);e.target.value=""});
const HD={theme:"default",layout:"right",logo:"on",size:"m",motion:"on"};
const HO={theme:["Colour",[["default","Default"],["burgundy","Burgundy"],["forest","Forest"],["olive","Olive"],["brown","Brown"]]],layout:["Layout",[["right","Logo right"],["left","Logo left"],["center","Centered"]]],logo:["Logo",[["on","Show"],["off","Hide"]]],size:["Text size",[["s","Small"],["m","Medium"],["l","Large"]]],motion:["Logo animation",[["on","On"],["off","Off"]]]};
