function syncH(){const h=document.querySelector(".hero");if(!h)return;for(const k in H)h.dataset[k]=H[k];document.querySelectorAll(".hs-panel [data-hk]").forEach(x=>x.classList.toggle("on",H[x.dataset.hk]===x.dataset.hv))}
function initHero(){const h=document.querySelector(".hero");if(!h||!h.querySelector("img"))return;
h.insertAdjacentHTML("beforeend",`<button class="hs-btn" aria-label="Hero settings" aria-expanded="false" aria-controls="hsp"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 7h9M17 7h3M4 17h3M11 17h9"/><circle cx="15" cy="7" r="2.2"/><circle cx="9" cy="17" r="2.2"/></svg></button><div class="hs-panel" id="hsp" hidden role="dialog" aria-label="Hero settings"><h4>Settings</h4>${h.querySelector("img")?`<div class="hs-l">Logo image</div><label class="btn sm" for="hs-file" style="display:inline-block;cursor:pointer">Upload your logo</label><input type="file" id="hs-file" accept="image/*" hidden><button class="btn sm" id="hs-dl" style="margin-left:.3rem">Default logo</button><br>`:"<br>"}<button class="btn sm" id="hs-reset">Reset all</button></div>`);syncH()}
document.addEventListener("click",e=>{const p=document.getElementById("hsp"),b=document.querySelector(".hs-btn");if(!p)return;
if(e.target.closest(".hs-btn")){p.hidden=!p.hidden;b.setAttribute("aria-expanded",String(!p.hidden));return}
const o=e.target.closest("[data-hk]");if(o){H[o.dataset.hk]=o.dataset.hv;saveH();syncH();return}
if(e.target.closest("#hs-dl")){CL=null;try{localStorage.removeItem("hero-logo")}catch(x){}setLogo();return}
if(e.target.closest("#hs-reset")){H={...HD};saveH();syncH();CL=null;try{localStorage.removeItem("hero-logo")}catch(x){}setLogo();return}
if(!e.target.closest(".hs-panel")){p.hidden=true;b.setAttribute("aria-expanded","false")}});
document.addEventListener("keydown",e=>{if(e.key==="Escape"){const p=document.getElementById("hsp");if(p){p.hidden=true;document.querySelector(".hs-btn").setAttribute("aria-expanded","false")}}});
const LK={
who:["WHO: One Health","https://www.who.int/health-topics/one-health"],
cdc:["CDC: One Health","https://www.cdc.gov/one-health/"],
rab:["WHO: Rabies fact sheet","https://www.who.int/news-room/fact-sheets/detail/rabies"],
wsava:["WSAVA: Global Vaccination Guidelines","https://wsava.org/guidelines/vaccination-guidelines"],
amr:["WOAH: Prudent use of antimicrobials (factsheet)","https://www.woah.org/en/document/factsheet-aiming-for-a-more-prudent-use-of-antimicrobials-the-progress-of-the-animal-health-sector/"],
woah:["WOAH: World Organisation for Animal Health","https://www.woah.org/"],
fao:["FAO: Animal Health","https://www.fao.org/animal-health/en"],
icar:["ICAR: Indian Council of Agricultural Research","https://icar.org.in/"],
dahd:["Dept. of Animal Husbandry and Dairying, India","https://dahd.nic.in/"],
nddb:["NDDB: National Dairy Development Board","https://www.nddb.coop/"],
vci:["Veterinary Council of India","https://www.vci.gov.in/"]};
const SRC={foods:["icar","dahd","fao"],treatments:["woah","amr","vci"],diseases:["woah","who","rab"],prevention:["wsava","rab","dahd"],welfare:["woah","fao","dahd"],breeds:["icar","dahd","fao"],reproduction:["icar","nddb","dahd"],research:["icar","woah","who"],education:["vci","icar","dahd"],institutions:["icar","vci","dahd"],extension:["dahd","icar","nddb"],onehealth:["who","cdc","amr"]};
const srcB=k=>`<div class="ad"><h4>Learn more: official information sources</h4><ul class="ck">${k.map(x=>`<li><a href="${LK[x][1]}" target="_blank" rel="noopener">${LK[x][0]} &#8599;</a></li>`).join("")}</ul><p class="muted">These links open the organisation website. Use its search for the specific topic.</p></div>`;
const AD=[
{s:[["What One Health means","One Health recognises that the health of people, animals and the environment is closely linked. Problems in one area, such as a disease in livestock or polluted water, can affect the others."],["Why it matters","Most new infectious diseases in people have an animal origin, and food safety, antibiotic resistance and climate all cut across human, animal and environmental health. Veterinarians, doctors, farmers and environmental specialists must work together."],["Everyday examples","&bull; Vaccinating dogs against rabies protects people<br>&bull; Safe milk and meat handling prevents foodborne illness<br>&bull; Responsible antibiotic use slows resistance<br>&bull; Healthy wildlife and clean water support ecosystems"],["What you can do","Vaccinate pets and livestock, wash hands after handling animals, report unusual animal illness early and use medicines only as advised by a professional."]],l:["who","cdc","fao"]},
{s:[["How vaccines work","A vaccine shows the immune system a harmless form of a germ so the body can respond faster if it meets the real disease. This lowers the chance and severity of illness."],["Core and non-core vaccines","Global small-animal guidelines describe core vaccines as those recommended for all animals because the diseases are widespread and serious, and non-core vaccines as those given based on lifestyle and local risk. A local veterinarian decides which apply."],["Young animals","Puppies and kittens are usually vaccinated in a series of visits until about 16 weeks of age or older, because protection from the mother can interfere with early vaccines. Follow the schedule your veterinarian gives."],["Rabies","Rabies is fatal and spreads to people. Vaccinating dogs is the most effective way to prevent human rabies. Local law may require rabies vaccination."],["Keep records","Keep a vaccination card, bring it to every visit and do not skip boosters without veterinary advice."]],l:["wsava","rab","dahd"]},
{s:[["Why clean milk matters","Clean milk is safer, keeps longer and earns better prices. Hygiene at every step also protects the udder from infection such as mastitis."],["Key hygiene steps","&bull; Keep animals, housing and the milking area clean and dry<br>&bull; Wash hands and clean milking utensils before use<br>&bull; Clean the udder and teats before milking and dry them<br>&bull; Milk sick or recently treated animals last<br>&bull; Cool milk and deliver it promptly"],["Watch for mastitis","Swollen or painful udder, clots or watery milk, reduced yield and fever call for a veterinarian."],["Medicines and milk","If an animal has been treated with medicines, follow the veterinarian instructions about how long milk must be discarded before it is used or sold."]],l:["nddb","dahd","icar"]},
{s:[["Why roughage comes first","Cattle, buffaloes, goats and sheep are ruminants. Microbes in the rumen digest fibre, so good green and dry fodder is the base of the diet, not an optional extra."],["A balanced ration","Combine green fodder, dry fodder, a suitable concentrate and a mineral mixture for the stage of production. Ask a livestock nutrition expert to plan it, because needs differ for calves, pregnant and milking animals."],["Common feeding risks","&bull; Sudden diet changes upset the rumen<br>&bull; Too much grain can cause acidosis<br>&bull; Wet, lush fodder can cause bloat<br>&bull; Mouldy or spoilt feed can poison animals"],["Water","Clean water should be available at all times. Milk production drops quickly when water is limited."]],l:["icar","dahd","fao"]},
{s:[["What it is","Antimicrobial resistance happens when germs such as bacteria change so medicines no longer kill them. Infections then become harder to treat in animals and people."],["How it develops","Overuse and misuse of antibiotics, such as using them for viral illness, giving partial courses or using leftover medicine, helps resistant germs survive and spread."],["The animal link","Resistant germs can pass between animals, people, food and the environment, which is why AMR is a One Health issue."],["What owners and farmers can do","&bull; Use antibiotics only when a veterinarian prescribes them<br>&bull; Give the full prescribed course<br>&bull; Never share or save leftover medicine<br>&bull; Prevent disease with vaccination, hygiene and good nutrition"]],l:["amr","who","cdc"]},
{s:[["Where veterinary graduates work","Clinical practice, government veterinary services, universities and research institutes, dairy, poultry and feed industries, food safety and public health, wildlife and zoo care."],["Skills that help","Science and clinical skills, communication with animal owners and farmers, teamwork, and a commitment to animal welfare and ethics."],["The education route","The professional degree in India is commonly BVSc and AH, followed by optional MVSc and PhD specialisations. Check each institution for exact duration and admission steps."],["Where to find official information","The Veterinary Council of India regulates veterinary education and practice, and ICAR supports research and education in agriculture and animal sciences."]],l:["vci","icar","dahd"]}];
const artBody=i=>{const d=AD[i];return `<div class="ad">${d.s.map(x=>`<h4>${x[0]}</h4><p>${x[1]}</p>`).join("")}<h4>Learn more: official sources</h4><ul class="ck">${d.l.map(k=>`<li><a href="${LK[k][1]}" target="_blank" rel="noopener">${LK[k][0]} &#8599;</a></li>`).join("")}</ul><p class="muted">Educational summary written for this platform. It does not replace veterinary advice.</p></div>`};
